/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    getOutOfRoundAttackSpeedPreview, getOutOfRoundLifestealPreview, getOutOfRoundFreeUpgradeChancePreview, getWorkshopUtilityLevelSkipChance
 * depends    src/data/workshop/progress-definitions, src/mechanics/enemies/level-skip, src/mechanics/primitives/constants, src/mechanics/workshop/types
 * used by    src/calculators/specs.generated, src/mechanics/workshop/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import {
  ATTACK_SPEED_LEVEL_SCALE,
  ATTACK_SPEED_OFFSET,
  FREE_UPGRADE_LEVEL_SCALE,
  LIFESTEAL_TIER_POW,
  LIFESTEAL_TIER_SCALE,
} from '../primitives/constants'
import { getWorkshopStatDefinitionByKey } from '../../data/workshop/progress-definitions'
import { LEVEL_SKIP_WORKSHOP_BASE } from '../enemies/level-skip'
import type { AttackSpeedPreviewInput, FreeUpgradeChancePreviewInput, LifestealPreviewInput } from './types'

export function getOutOfRoundAttackSpeedPreview(input: AttackSpeedPreviewInput): number {
  const L = Math.max(0, input.workshopLevel)
  let core = (L * ATTACK_SPEED_LEVEL_SCALE + ATTACK_SPEED_OFFSET) * input.catalogMult * input.moduleMult
  if (input.relicAttackSpeedMult != null) core *= input.relicAttackSpeedMult
  let raw = core + input.workshopCurveMult
  raw *= (input.labMult ?? 0) + 1
  raw *= (input.storedMult ?? 0) + 1
  if (input.cardMult != null) raw *= input.cardMult
  return raw
}

export function getOutOfRoundLifestealPreview(input: LifestealPreviewInput): number {
  const tierPow = Math.pow(Math.max(0, input.catalogTier), LIFESTEAL_TIER_POW)
  return input.workshopCurveValue + input.catalogTier * LIFESTEAL_TIER_SCALE * tierPow
}

/** Shared tail for free attack/defense/utility upgrade chance getters. */
export function getOutOfRoundFreeUpgradeChancePreview(input: FreeUpgradeChancePreviewInput): number {
  let core = input.workshopCurveValue + input.levelField * FREE_UPGRADE_LEVEL_SCALE
  if (input.enhancementRowAdd != null) core += input.enhancementRowAdd
  core = (core + (input.labMult ?? 0)) + 1
  if (input.cardMultA != null) core *= input.cardMultA
  if (input.cardMultB != null) core *= input.cardMultB
  return core
}

/**
 * Out-of-round level skip chance for utility ELS stats from `workshop.json`.
 * Preview chance = workshop.json `value` at level L (= 0.0005 + L × 0.0005 for utility ELS).
 */
export function getWorkshopUtilityLevelSkipChance(statKey: string, utilityLevel: number): number | null {
  const stat = getWorkshopStatDefinitionByKey(statKey)
  if (!stat || stat.levels.length === 0) return null

  const level = Math.max(0, Math.floor(utilityLevel))
  const clampedLevel = Math.min(level, stat.maxLevel)
  const row = stat.levels.find(entry => entry.level === clampedLevel)
  const baseRow = stat.levels.find(entry => entry.level === stat.minLevel) ?? stat.levels[0]
  if (!row || !baseRow) return null

  return LEVEL_SKIP_WORKSHOP_BASE + row.value - baseRow.value
}
